package circuitbreaker

import (
	"errors"
	"sync"
	"time"
)

// State represents the current state of the circuit breaker.
type State int

const (
	StateClosed State = iota
	StateOpen
	StateHalfOpen
)

// Config holds the configuration for the CircuitBreaker.
type Config struct {
	// FailureThreshold is the number of consecutive failures required to trip the breaker to Open state.
	FailureThreshold int
	// Timeout is the duration in milliseconds after which the breaker transitions from Open to HalfOpen.
	Timeout int
}

// CircuitBreaker implements the circuit breaker pattern.
type CircuitBreaker struct {
	mu               sync.Mutex
	state            State
	failureCount     int
	lastFailureTime  time.Time
	failureThreshold int
	timeout          time.Duration
}

// New creates a new CircuitBreaker with the provided configuration.
// It returns an error if the configuration is invalid.
func New(cfg Config) (*CircuitBreaker, error) {
	if cfg.FailureThreshold <= 0 {
		return nil, errors.New("failure threshold must be greater than 0")
	}
	if cfg.Timeout <= 0 {
		return nil, errors.New("timeout must be greater than 0")
	}

	return &CircuitBreaker{
		state:            StateClosed,
		failureThreshold: cfg.FailureThreshold,
		timeout:          time.Duration(cfg.Timeout) * time.Millisecond,
	}, nil
}

// Allow returns true if the request should proceed.
// If the breaker is Open and the timeout has not elapsed, it returns false.
// If the breaker is Open and the timeout has elapsed, it transitions to HalfOpen and returns true.
// If the breaker is Closed or HalfOpen, it returns true.
func (cb *CircuitBreaker) Allow() bool {
	cb.mu.Lock()
	defer cb.mu.Unlock()

	switch cb.state {
	case StateClosed:
		return true
	case StateOpen:
		if time.Since(cb.lastFailureTime) >= cb.timeout {
			cb.state = StateHalfOpen
			return true
		}
		return false
	case StateHalfOpen:
		return true
	default:
		// Defensive programming: if state is unknown, fail closed.
		return false
	}
}

// RecordSuccess records a successful request.
// If the breaker is in HalfOpen state, it transitions to Closed and resets the failure count.
func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()

	if cb.state == StateHalfOpen {
		cb.state = StateClosed
	}
	cb.failureCount = 0
}

// RecordFailure records a failed request.
// If the breaker is in HalfOpen state, it transitions to Open.
// If the breaker is in Closed state, it increments the failure count.
// If the failure count exceeds the threshold, it transitions to Open.
func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()

	cb.lastFailureTime = time.Now()

	switch cb.state {
	case StateHalfOpen:
		cb.state = StateOpen
	case StateClosed:
		cb.failureCount++
		if cb.failureCount >= cb.failureThreshold {
			cb.state = StateOpen
		}
	case StateOpen:
		// Already open, just update the last failure time to extend the open period.
		// This is a design choice: some implementations reset the timer on every failure while open.
		// Here we update lastFailureTime so the timeout is based on the most recent failure.
	}
}
